import React from 'react'
import axios from 'axios';
import { useParams, useNavigate } from 'react-router';
import { useState, useEffect } from 'react';



function UpdateProfile() {
    const { id } = useParams();
    
  return (
    <div>
      <h1>Update Profile</h1>
      <form onSubmit={(e) => onSubmit(e)}>

        <label htmlFor="fullname">fullname</label><br />
        <input type="text" id="fullname" name="fullname" onChange={(e) => onInputChange(e)} value={fullname} required />
        <br />

        <label htmlFor="email">email</label><br />
        <input type="email" id="email" name="email" value={email} onChange={(e) => onInputChange(e)} required /><br />

        <label htmlFor="password">password</label><br />
        <input type="password" id="password" name="password" value={password} onChange={(e) => onInputChange(e)} required /><br />

        <label htmlFor="phone">phone</label><br />
        <input type="text" id="phone" name="phone" value={phone} onChange={(e) => onInputChange(e)} />
        <br />
        <button type="submit" className="fom_btn">register</button>
      </form>
    </div>
  )
}

export default UpdateProfile
